    @Test
    fun ofSubscriptionPlanVersionChanged() {
        val subscriptionPlanVersionChanged =
            SubscriptionPlanVersionChangedWebhookEvent.builder()
                .id("id")
                .createdAt(OffsetDateTime.parse("2019-12-27T18:11:19.117Z"))
                .properties(
                    SubscriptionPlanVersionChangedWebhookEvent.Properties.builder()
                        .effectiveDate("effective_date")
                        .newPlanVersionNumber(0L)
                        .previousPlanVersionNumber(0L)
                        .build()
