    @Test
    fun ofSubscriptionStarted() {
        val subscriptionStarted =
            SubscriptionStartedWebhookEvent.builder()
                .id("id")
                .createdAt(OffsetDateTime.parse("2019-12-27T18:11:19.117Z"))
                .properties(JsonValue.from(mapOf<String, Any>()))
                .subscription(
